+      }
+
+      .num {
+        font-variant-numeric: tabular-nums;
+        font-family: var(--mono);
+      }
+
+      .muted {
+        color: var(--muted);
+      }
+
+      .footer {
+        margin-top: 34px;
+        padding-top: 14px;
+        border-top: 1px solid var(--border);
+        color: var(--muted);
+        font-size: 12.5px;
+      }
+
+      @media (max-width: 980px) {
+        .kpi {
+          grid-column: span 6;
+        }
+
+        .kpi.wide {
+          grid-column: span 12;
+        }
+
+        .col-7,
+        .col-5,
+        .col-6 {
+          grid-column: span 12;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <div class="container">
+      <header>
+        <div class="title">
+          <div>
+            <h1>{{ title }}</h1>
+            <div class="subtitle">{{ one_liner }}</div>
+          </div>
+          <div class="meta">
+            <div class="pill">
+              <span>Generated</span>
+              <span class="num">{{ generated_at }}</span>
+              <span class="muted">(UTC)</span>
+            </div>
+          </div>
+        </div>
+        <div class="meta" style="margin-top: 10px">
+          Dataset: UNODC intentional homicide rates (via provided <span class="num">data.csv</span>). Rows: <span class="num">{{ dataset_rows }}</span>. Countries/territories: <span class="num">{{ countries_total }}</span>. Years: <span class="num">{{ years_min }}–{{ years_max }}</span>.
+        </div>
+      </header>
+
+      <section class="grid kpi-grid">
+        {% for kpi in kpis %}
+        <div class="card kpi {{ 'wide' if kpi.get('wide') else '' }}">
+          <div class="label">{{ kpi.label }}</div>
+          <div class="value">{{ kpi.value }}</div>
+          <div class="note">{{ kpi.note }}</div>
+        </div>
+        {% endfor %}
+      </section>
+
+      <section class="section">
+        <div class="section-title">
+          <h2>1) Global Homicide Rate Overview</h2>
+          <div class="hint">Backbone time series • unbalanced panel awareness</div>
+        </div>
+        <div class="grid two-col">
+          <div class="chart col-7">
+            <div id="chart_global"></div>
+            <div class="caption">Global central tendency across reporting countries (median and mean homicide rate per 100k). Coverage line (right axis) indicates changing number of reporting countries.</div>
+          </div>
+          <div class="col-5">
+            <div class="card callout">
+              <h3>Interpretation Guidance</h3>
+              <p>Year-to-year changes reflect both real trend movement <em>and</em> shifts in reporting coverage. Interpret global averages as summaries of reporting countries, not fully representative global population estimates.</p>
+            </div>
+            <div style="height: 10px"></div>
+            <div class="card callout warn">
+              <h3>Coverage Caveat (Critical)</h3>
+              <p>In {{ latest_year }}, only <span class="num">{{ latest_year_countries }}</span> of <span class="num">{{ countries_total }}</span> countries/territories report <span class="num">sex=both</span>, <span class="num">age_group=ALL</span> — a coverage rate of <span class="num">{{ latest_year_coverage_rate }}</span>.</p>
+            </div>
+          </div>
+        </div>
+      </section>
+
+      <section class="section">
+        <div class="section-title">
+          <h2>2) Regional &amp; Country-Level Comparison</h2>
+          <div class="hint">Top/bottom outliers • most recent year</div>
+        </div>
+        <div class="grid two-col">
+          <div class="card col-6">
+            <h2>Top 10 countries ({{ latest_year }})</h2>
+            <table>
+              <thead>
+                <tr>
+                  <th>Rank</th>
+                  <th>Country / territory</th>
+                  <th class="num">Rate per 100k</th>
+                </tr>
+              </thead>
+              <tbody>
+                {% for row in top10_latest %}
+                <tr>
+                  <td class="num">{{ loop.index }}</td>
+                  <td>{{ row.country }}</td>
+                  <td class="num">{{ row.homicide_rate_fmt }}</td>
+                </tr>
+                {% endfor %}
+              </tbody>
+            </table>
+            <div class="muted" style="margin-top: 8px; font-size: 12.5px">Computed from rows where <span class="num">sex=both</span> and <span class="num">age_group=ALL</span>.</div>
+          </div>
+          <div class="card col-6">
+            <h2>Bottom 10 countries ({{ latest_year }})</h2>
+            <table>
+              <thead>
+                <tr>
+                  <th>Rank</th>
+                  <th>Country / territory</th>
+                  <th class="num">Rate per 100k</th>
+                </tr>
+              </thead>
+              <tbody>
+                {% for row in bottom10_latest %}
+                <tr>
+                  <td class="num">{{ loop.index }}</td>
+                  <td>{{ row.country }}</td>
+                  <td class="num">{{ row.homicide_rate_fmt }}</td>
+                </tr>
+                {% endfor %}
+              </tbody>
+            </table>
+            <div class="muted" style="margin-top: 8px; font-size: 12.5px">Values near zero can reflect truly low homicide victimization and/or reporting/measurement nuance.</div>
+          </div>
+        </div>
+      </section>
+
+      <section class="section">
+        <div class="section-title">
+          <h2>3) Gender Disparity in Homicide Victimization</h2>
+          <div class="hint">Male-to-female ratio KPI emphasized</div>
+        </div>
+        <div class="grid two-col">
+          <div class="chart col-7">
+            <div id="chart_sex_ratio"></div>
+            <div class="caption">Male-to-female homicide rate ratio over time (computed using countries with both male and female rates for <span class="num">age_group=ALL</span> in each year). Dashed line shows median of country-level ratios; solid line shows ratio of global mean male rate to global mean female rate.</div>
+          </div>
+          <div class="col-5">
+            <div class="card callout">
+              <h3>What this KPI means</h3>
+              <p>A ratio &gt; 1 indicates higher male victimization rates. This report uses cross-country aggregation (not population-weighted); it highlights relative disparity patterns among reporting countries.</p>
+            </div>
+            <div style="height: 10px"></div>
+            <div class="card callout good">
+              <h3>Headline</h3>
+              <p>In {{ latest_year }}, the male-to-female ratio (mean-of-rates) is <span class="num">{{ male_female_ratio_latest }}</span>, based on <span class="num">{{ sex_common_countries_latest }}</span> countries/territories reporting both sexes.</p>
+            </div>
+          </div>
+        </div>
+      </section>
+
+      <section class="section">
+        <div class="section-title">
+          <h2>4) Age Group Analysis</h2>
+          <div class="hint">Availability-driven; no imputation</div>
+        </div>
+        <div class="card callout bad">
+          <h3>Limitation: Age-group totals are not available for <span class="num">sex=both</span></h3>
+          <p>
+            The dataset includes age-group breakdowns only for <span class="num">sex=male</span> and <span class="num">sex=female</span> (no <span class="num">sex=both</span> rows for age groups other than <span class="num">ALL</span>). As a result, this report cannot estimate overall (both-sexes) age-group homicide rates without imputation.
+          </p>
+        </div>
+        <div style="height: 10px"></div>
+        <div class="chart">
+          <div id="chart_age_sex"></div>
+          <div class="caption">Age-group rates by sex (latest year with any age-group data). Use this to identify which age bands are highest-risk among reporting countries.</div>
+        </div>
+      </section>
+
+      <section class="section">
+        <div class="section-title">
+          <h2>5) Notable Country-Level Trends &amp; Outliers</h2>
+          <div class="hint">Dramatic improvements and deteriorations</div>
+        </div>
+        <div class="grid two-col">
+          <div class="card col-6">
+            <h2>Largest decreases (≥10-year span)</h2>
+            <table>
+              <thead>
+                <tr>
+                  <th>Country / territory</th>
+                  <th class="num">First (yr, rate)</th>
+                  <th class="num">Last (yr, rate)</th>
+                  <th class="num">Δ rate</th>
+                </tr>
+              </thead>
+              <tbody>
+                {% for row in outliers_improvements %}
+                <tr>
+                  <td>{{ row.country }}</td>
+                  <td class="num">{{ row.first_fmt }}</td>
+                  <td class="num">{{ row.last_fmt }}</td>
+                  <td class="num" style="color: var(--good)">{{ row.change_fmt }}</td>
+                </tr>
+                {% endfor %}
+              </tbody>
+            </table>
+          </div>
+          <div class="card col-6">
+            <h2>Largest increases (≥10-year span)</h2>
+            <table>
+              <thead>
+                <tr>
+                  <th>Country / territory</th>
+                  <th class="num">First (yr, rate)</th>
+                  <th class="num">Last (yr, rate)</th>
+                  <th class="num">Δ rate</th>
+                </tr>
+              </thead>
+              <tbody>
+                {% for row in outliers_deteriorations %}
+                <tr>
+                  <td>{{ row.country }}</td>
+                  <td class="num">{{ row.first_fmt }}</td>
+                  <td class="num">{{ row.last_fmt }}</td>
+                  <td class="num" style="color: var(--bad)">{{ row.change_fmt }}</td>
+                </tr>
+                {% endfor %}
+              </tbody>
+            </table>
+          </div>
+        </div>
+        <div style="height: 10px"></div>
+        <div class="card callout warn">
+          <h3>Outlier interpretation</h3>
+          <p>These changes use each country’s first and last observed years in the dataset. Differences may reflect real change, methodological updates, coverage gaps, or discontinuities in reporting.</p>
+        </div>
+      </section>
+
+      <section class="section">
+        <div class="section-title">
+          <h2>6) Data Limitations &amp; Policy Recommendations</h2>
+          <div class="hint">Unbalanced panel • coverage gaps • action orientation</div>
+        </div>
+        <div class="grid two-col">
+          <div class="card col-6">
+            <h2>Key data limitations</h2>
+            <ul style="margin: 8px 0 0; padding-left: 18px; color: var(--text)">
+              <li><strong>Unbalanced panel:</strong> countries enter/exit the series over time; means/medians are conditional on reporters in each year.</li>
+              <li><strong>Coverage decline at series end:</strong> reporting in 2023 is materially lower than peak coverage years in the late 2010s.</li>
+              <li><strong>Age-group constraint:</strong> age bands are sex-disaggregated only (no both-sexes age totals), limiting direct cross-age comparisons for overall populations.</li>
+              <li><strong>Territories included:</strong> some entries are territories; comparisons should consider administrative scope.</li>
+              <li><strong>UK caveat (per dataset doc):</strong> United Kingdom entries may refer to England and Wales only.</li>
+            </ul>
+          </div>
+          <div class="card col-6">
+            <h2>Policy-relevant takeaways (data-driven)</h2>
+            <ul style="margin: 8px 0 0; padding-left: 18px; color: var(--text)">
+              <li><strong>Target high-rate hotspots:</strong> concentrate prevention and investigative capacity where latest rates are extreme (top decile), while monitoring spillover risks.</li>
+              <li><strong>Design gender-responsive interventions:</strong> male victimization remains substantially higher, suggesting priority for violence reduction among men and boys while sustaining protections for women.</li>
+              <li><strong>Invest in statistical systems:</strong> reporting completeness is itself a capability; gaps hinder trend detection and accountability.</li>
+              <li><strong>Use multi-year smoothing for decisions:</strong> prefer 3–5 year windows where feasible to reduce sensitivity to single-year coverage changes.</li>
+              <li><strong>Validate outlier shifts:</strong> large changes should trigger contextual review (methodology, conflict, organized crime, governance, or data breaks).</li>
+            </ul>
+          </div>
+        </div>
+      </section>
+
+      <div class="footer">
+        <div><strong>Method note:</strong> All statistics are computed directly from provided <span class="num">data.csv</span>. No imputation or external sources were used.</div>
+      </div>
+    </div>
+
+    <script>
+      // Minimal inline SVG charting (no external deps)
+      function fmt(x, digits = 2) {
+        if (x === null || x === undefined || Number.isNaN(x)) return "NA";
+        const v = Number(x);
+        if (!Number.isFinite(v)) return "NA";
+        return v.toFixed(digits);
+      }
+
+      function el(tag, attrs = {}, children = []) {
+        const node = document.createElementNS("http://www.w3.org/2000/svg", tag);
+        for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, String(v));
+        for (const c of children) node.appendChild(c);
+        return node;
+      }
+
+      function makeChart(containerId, spec) {
+        const container = document.getElementById(containerId);
+        if (!container) return;
+        container.innerHTML = "";
+
+        const width = spec.width || 760;
+        const height = spec.height || 360;
+        const pad = { left: 46, right: 46, top: 18, bottom: 34, ...(spec.pad || {}) };
+        const plotW = width - pad.left - pad.right;
+        const plotH = height - pad.top - pad.bottom;
+
+        const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
+        svg.setAttribute("width", "100%");
+        svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
+        svg.style.display = "block";
+        svg.style.borderRadius = "12px";
+        svg.style.background = "rgba(255,255,255,0.02)";
+
+        // grid
+        const grid = el("g", { opacity: "0.55" });
+        const gridLines = spec.gridLines ?? 5;
+        for (let i = 0; i <= gridLines; i++) {
+          const y = pad.top + (plotH * i) / gridLines;
+          grid.appendChild(
+            el("line", {
+              x1: pad.left,
+              y1: y,
+              x2: pad.left + plotW,
+              y2: y,
+              stroke: "rgba(255,255,255,0.08)",
+              "stroke-width": 1,
+            })
+          );
+        }
+        svg.appendChild(grid);
+
+        // axes
+        svg.appendChild(
+          el("line", {
+            x1: pad.left,
+            y1: pad.top,
+            x2: pad.left,
+            y2: pad.top + plotH,
+            stroke: "rgba(255,255,255,0.18)",
+            "stroke-width": 1,
+          })
+        );
+        svg.appendChild(
+          el("line", {
+            x1: pad.left,
+            y1: pad.top + plotH,
+            x2: pad.left + plotW,
+            y2: pad.top + plotH,
+            stroke: "rgba(255,255,255,0.18)",
+            "stroke-width": 1,
+          })
+        );
+        if (spec.y2) {
+          svg.appendChild(
+            el("line", {
+              x1: pad.left + plotW,
+              y1: pad.top,
+              x2: pad.left + plotW,
+              y2: pad.top + plotH,
+              stroke: "rgba(255,255,255,0.18)",
+              "stroke-width": 1,
+            })
+          );
+        }
+
+        const xMin = spec.x.domain[0];
+        const xMax = spec.x.domain[1];
+        const xScale = (x) => pad.left + ((x - xMin) / (xMax - xMin)) * plotW;
+
+        const yMin = spec.y.domain[0];
+        const yMax = spec.y.domain[1];
+        const yScale = (y) => pad.top + (1 - (y - yMin) / (yMax - yMin)) * plotH;
+
+        let y2Scale = null;
+        if (spec.y2) {
+          const y2Min = spec.y2.domain[0];
+          const y2Max = spec.y2.domain[1];
+          y2Scale = (y) => pad.top + (1 - (y - y2Min) / (y2Max - y2Min)) * plotH;
+        }
+
+        // y labels
+        const yLabelCount = spec.y.ticks ?? 5;
+        for (let i = 0; i <= yLabelCount; i++) {
+          const v = yMin + ((yMax - yMin) * i) / yLabelCount;
+          const y = yScale(v);
+          const t = document.createElementNS("http://www.w3.org/2000/svg", "text");
+          t.setAttribute("x", String(pad.left - 8));
+          t.setAttribute("y", String(y + 4));
+          t.setAttribute("text-anchor", "end");
+          t.setAttribute("fill", "rgba(255,255,255,0.65)");
+          t.setAttribute("font-size", "11");
+          t.setAttribute("font-family", "ui-monospace, SFMono-Regular, Menlo, monospace");
+          t.textContent = fmt(v, spec.y.tickDigits ?? 0);
+          svg.appendChild(t);
+        }
+
+        if (spec.y2) {
+          const y2LabelCount = spec.y2.ticks ?? 5;
+          const y2Min = spec.y2.domain[0];
+          const y2Max = spec.y2.domain[1];
+          for (let i = 0; i <= y2LabelCount; i++) {
+            const v = y2Min + ((y2Max - y2Min) * i) / y2LabelCount;
+            const y = y2Scale(v);
+            const t = document.createElementNS("http://www.w3.org/2000/svg", "text");
+            t.setAttribute("x", String(pad.left + plotW + 8));
+            t.setAttribute("y", String(y + 4));
+            t.setAttribute("text-anchor", "start");
+            t.setAttribute("fill", "rgba(255,255,255,0.65)");
+            t.setAttribute("font-size", "11");
+            t.setAttribute("font-family", "ui-monospace, SFMono-Regular, Menlo, monospace");
+            t.textContent = fmt(v, spec.y2.tickDigits ?? 0);
+            svg.appendChild(t);
+          }
+        }
+
+        // x labels
+        const xTickYears = spec.x.ticks;
+        for (const yr of xTickYears) {
+          const x = xScale(yr);
+          svg.appendChild(
+            el("line", {
+              x1: x,
+              y1: pad.top + plotH,
+              x2: x,
+              y2: pad.top + plotH + 4,
+              stroke: "rgba(255,255,255,0.25)",
+              "stroke-width": 1,
+            })
+          );
+          const t = document.createElementNS("http://www.w3.org/2000/svg", "text");
+          t.setAttribute("x", String(x));
+          t.setAttribute("y", String(pad.top + plotH + 18));
+          t.setAttribute("text-anchor", "middle");
+          t.setAttribute("fill", "rgba(255,255,255,0.65)");
+          t.setAttribute("font-size", "11");
+          t.setAttribute("font-family", "ui-monospace, SFMono-Regular, Menlo, monospace");
+          t.textContent = String(yr);
+          svg.appendChild(t);
+        }
+
+        // series
+        for (const s of spec.series) {
+          const points = s.data
+            .filter((d) => d.x !== null && d.y !== null && Number.isFinite(d.y))
+            .map((d) => [xScale(d.x), (s.axis === "y2" ? y2Scale(d.y) : yScale(d.y))]);
+          if (points.length === 0) continue;
+          const d = points.map((p, i) => `${i === 0 ? "M" : "L"} ${p[0].toFixed(2)} ${p[1].toFixed(2)}`).join(" ");
+          svg.appendChild(
+            el("path", {
+              d,
+              fill: "none",
+              stroke: s.color,
+              "stroke-width": s.width ?? 2.2,
+              "stroke-dasharray": s.dash ?? "",
+              opacity: s.opacity ?? 1,
+            })
+          );
+        }
+
+        // legend
+        const legend = document.createElement("div");
+        legend.style.display = "flex";
+        legend.style.flexWrap = "wrap";
+        legend.style.gap = "10px";
+        legend.style.marginTop = "8px";
+        legend.style.color = "rgba(255,255,255,0.75)";
+        legend.style.fontSize = "12px";
+        for (const s of spec.series) {
+          const item = document.createElement("div");
+          item.style.display = "inline-flex";
+          item.style.alignItems = "center";
+          item.style.gap = "8px";
+          const sw = document.createElement("span");
+          sw.style.width = "18px";
+          sw.style.height = "0px";
+          sw.style.borderTop = `${s.width ?? 2}px ${s.dash ? "dashed" : "solid"} ${s.color}`;
+          sw.style.opacity = s.opacity ?? 1;
+          item.appendChild(sw);
+          const label = document.createElement("span");
+          label.textContent = s.label;
+          item.appendChild(label);
+          legend.appendChild(item);
+        }
+
+        container.appendChild(svg);
+        container.appendChild(legend);
+      }
+
+      const REPORT = {{ report_json | safe }};
+
+      // Global chart (mean/median + coverage)
+      const global = REPORT.global_time_series;
+      const years = global.map((d) => d.year);
+      const yearMin = Math.min(...years);
+      const yearMax = Math.max(...years);
+      const meanSeries = global.map((d) => ({ x: d.year, y: d.mean }));
+      const medianSeries = global.map((d) => ({ x: d.year, y: d.median }));
+      const covSeries = global.map((d) => ({ x: d.year, y: d.countries }));
+      const yMax = Math.max(
+        ...global.map((d) => Math.max(d.mean ?? 0, d.median ?? 0)).filter((v) => Number.isFinite(v))
+      );
+      const covMax = Math.max(...global.map((d) => d.countries).filter((v) => Number.isFinite(v)));
+
+      const xTicks = [];
+      for (let y = yearMin; y <= yearMax; y += 5) xTicks.push(y);
+      if (xTicks[xTicks.length - 1] !== yearMax) xTicks.push(yearMax);
+
+      makeChart("chart_global", {
+        width: 780,
+        height: 360,
+        x: { domain: [yearMin, yearMax], ticks: xTicks },
+        y: { domain: [0, Math.ceil(yMax * 1.05)], ticks: 5, tickDigits: 0 },
+        y2: { domain: [0, Math.ceil(covMax * 1.05)], ticks: 5, tickDigits: 0 },
+        series: [
+          { label: "Global median (rate)", data: medianSeries, color: "#7dd3fc", width: 2.6 },
+          { label: "Global mean (rate)", data: meanSeries, color: "#a78bfa", width: 2.2, dash: "6 4" },
+          { label: "Reporting countries", data: covSeries, color: "rgba(255,255,255,0.55)", width: 1.8, axis: "y2" },
+        ],
+      });
+
+      // Sex ratio chart
+      const ratios = REPORT.sex_ratio_series;
+      const rYears = ratios.map((d) => d.year);
+      const rMin = Math.min(...rYears);
+      const rMax = Math.max(...rYears);
+      const ratioMean = ratios.map((d) => ({ x: d.year, y: d.ratio_mean_of_rates }));
+      const ratioMedian = ratios.map((d) => ({ x: d.year, y: d.ratio_median_of_country_ratios }));
+      const rYMax = Math.max(...ratios.map((d) => d.ratio_mean_of_rates).filter((v) => Number.isFinite(v)));
+      const rTicks = [];
+      for (let y = rMin; y <= rMax; y += 5) rTicks.push(y);
+      if (rTicks[rTicks.length - 1] !== rMax) rTicks.push(rMax);
+
+      makeChart("chart_sex_ratio", {
+        width: 780,
+        height: 330,
+        x: { domain: [rMin, rMax], ticks: rTicks },
+        y: { domain: [0, Math.ceil(rYMax * 1.10)], ticks: 5, tickDigits: 0 },
+        series: [
+          { label: "Ratio of global means (male/female)", data: ratioMean, color: "#7dd3fc", width: 2.6 },
+          { label: "Median country ratio", data: ratioMedian, color: "#a78bfa", width: 2.2, dash: "6 4" },
+        ],
+      });
+
+      // Age-sex chart: find latest year with any age-group data and chart mean by age_group for male & female
+      const ageRows = REPORT.age_rows || [];
+      const ageContainer = document.getElementById("chart_age_sex");
+      if (ageContainer) {
+        if (ageRows.length === 0) {
+          ageContainer.innerHTML = `<div class="muted">No age-group rows found.</div>`;
+        } else {
+          const yearsA = [...new Set(ageRows.map((d) => d.year))].sort((a, b) => a - b);
+          const latestAgeYear = yearsA[yearsA.length - 1];
+          const slice = ageRows.filter((d) => d.year === latestAgeYear);
+          const ageGroups = [...new Set(slice.map((d) => d.age_group))].sort();
+
+          function seriesForSex(sex) {
+            const points = [];
+            for (const g of ageGroups) {
+              const vals = slice
+                .filter((r) => r.sex === sex && r.age_group === g)
+                .map((r) => r.homicide_rate)
+                .filter((v) => Number.isFinite(v));
+              if (vals.length === 0) {
+                points.push({ x: g, y: null });
+              } else {
+                const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
+                points.push({ x: g, y: mean });
+              }
+            }
+            return points;
+          }
+
+          const malePts = seriesForSex("male");
+          const femalePts = seriesForSex("female");
+          const yMaxA = Math.max(
+            ...malePts
+              .concat(femalePts)
+              .map((p) => p.y)
+              .filter((v) => Number.isFinite(v))
+          );
+
+          // Build categorical x chart by mapping categories to numeric index
+          const xDomain = [0, ageGroups.length - 1];
+          const xTicksCat = ageGroups.map((g, i) => i).filter((_, i) => i % 1 === 0);
+
+          function mapCat(points) {
+            return points.map((p) => ({ x: ageGroups.indexOf(p.x), y: p.y }));
+          }
+
+          // Render and then add category labels manually
+          makeChart("chart_age_sex", {
+            width: 1040,
+            height: 330,
+            x: { domain: xDomain, ticks: xTicksCat },
+            y: { domain: [0, Math.ceil(yMaxA * 1.1)], ticks: 5, tickDigits: 0 },
+            series: [
+              { label: `Male (mean across reporters) — ${latestAgeYear}`, data: mapCat(malePts), color: "#7dd3fc", width: 2.6 },
+              { label: `Female (mean across reporters) — ${latestAgeYear}`, data: mapCat(femalePts), color: "#fb7185", width: 2.2, dash: "6 4" },
+            ],
+          });
+
+          // Replace numeric x-axis tick labels with age_group labels
+          const svg = ageContainer.querySelector("svg");
+          if (svg) {
+            const texts = [...svg.querySelectorAll("text")];
+            for (const t of texts) {
+              const y = Number(t.getAttribute("y"));
+              // crude: x-axis labels are near bottom
+              if (y > 290) {
+                const idx = Number(t.textContent);
+                if (Number.isFinite(idx) && ageGroups[idx]) t.textContent = ageGroups[idx].replace("_PLUS", "+").replace("_", "-");
+              }
+            }
+          }
+        }
